namespace SecretCustomer.Core.Entities;

public class AuditLog : BaseEntity
{
    public string EntityName { get; set; } = string.Empty;  // "Evaluation", "Assignment", vb.
    public Guid EntityId { get; set; }                      // İlgili entity'nin ID'si
    public string Action { get; set; } = string.Empty;      // "Create", "Update", "Delete", "Submit"
    public string? UserId { get; set; }                     // İşlemi yapan kullanıcı
    public string? UserName { get; set; }                   // Kullanıcı adı (cache)
    public string? IpAddress { get; set; }                  // İstek IP adresi
    public string? UserAgent { get; set; }                  // Browser/device bilgisi
    public DateTime Timestamp { get; set; } = DateTime.UtcNow;

    // Değişiklik detayları (JSON)
    public string? OldValues { get; set; }  // Önceki değerler (Update için)
    public string? NewValues { get; set; }  // Yeni değerler
}

using SecretCustomer.Core.Enums;

namespace SecretCustomer.Core.Entities;

public class EvaluationHistory : BaseEntity
{
    public Guid EvaluationId { get; set; }
    public Evaluation Evaluation { get; set; } = null!;

    public EvaluationStatus Status { get; set; }
    public string Action { get; set; } = string.Empty;  // "Started", "Paused", "Resumed", "Submitted"

    public Guid? UserId { get; set; }
    public User? User { get; set; }

    public string? IpAddress { get; set; }
    public DateTime ActionDate { get; set; } = DateTime.UtcNow;

    // Snapshot - O anki durum
    public decimal? ScoreSnapshot { get; set; }
    public string? NotesSnapshot { get; set; }
    public int? AnsweredQuestionsCount { get; set; }
    public int? TotalQuestionsCount { get; set; }
}

public class ApplicationDbContext : DbContext
{
    // ... mevcut DbSet'ler ...

    public DbSet<AuditLog> AuditLogs { get; set; }
    public DbSet<EvaluationHistory> EvaluationHistories { get; set; }

    // ...
}

using System.Text.Json;
using Microsoft.EntityFrameworkCore.ChangeTracking;

public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
{
    var auditEntries = new List<AuditLog>();
    var entries = ChangeTracker.Entries()
        .Where(e => e.Entity is not AuditLog && e.Entity is not EvaluationHistory)
        .Where(e => e.State == EntityState.Added ||
                    e.State == EntityState.Modified ||
                    e.State == EntityState.Deleted)
        .ToList();

    foreach (var entry in entries)
    {
        var auditLog = CreateAuditLog(entry);
        if (auditLog != null)
            auditEntries.Add(auditLog);
    }

    var result = await base.SaveChangesAsync(cancellationToken);

    // Audit log'ları kaydet
    if (auditEntries.Any())
    {
        await AuditLogs.AddRangeAsync(auditEntries, cancellationToken);
        await base.SaveChangesAsync(cancellationToken);
    }

    return result;
}

private AuditLog? CreateAuditLog(EntityEntry entry)
{
    var entity = entry.Entity as BaseEntity;
    if (entity == null) return null;

    var auditLog = new AuditLog
    {
        EntityName = entry.Entity.GetType().Name,
        EntityId = entity.Id,
        Action = entry.State.ToString(),
        Timestamp = DateTime.UtcNow
    };

    if (entry.State == EntityState.Modified)
    {
        var oldValues = new Dictionary<string, object?>();
        var newValues = new Dictionary<string, object?>();

        foreach (var property in entry.OriginalValues.Properties)
        {
            var originalValue = entry.OriginalValues[property];
            var currentValue = entry.CurrentValues[property];

            if (!Equals(originalValue, currentValue))
            {
                oldValues[property.Name] = originalValue;
                newValues[property.Name] = currentValue;
            }
        }

        auditLog.OldValues = JsonSerializer.Serialize(oldValues);
        auditLog.NewValues = JsonSerializer.Serialize(newValues);
    }
    else if (entry.State == EntityState.Added)
    {
        var newValues = entry.CurrentValues.Properties
            .ToDictionary(p => p.Name, p => entry.CurrentValues[p]);
        auditLog.NewValues = JsonSerializer.Serialize(newValues);
    }

    return auditLog;
}

public async Task<EvaluationDto> StartEvaluationAsync(Guid assignmentId, Guid? evaluatorId)
{
    // ... mevcut kod ...

    var evaluation = new Evaluation
    {
        AssignmentId = assignmentId,
        EvaluatorId = evaluatorId,
        Status = EvaluationStatus.InProgress,
        StartedAt = DateTime.UtcNow
    };

    var created = await _evaluationRepository.CreateAsync(evaluation);

    // YENİ: History kaydı
    await _context.EvaluationHistories.AddAsync(new EvaluationHistory
    {
        EvaluationId = created.Id,
        UserId = evaluatorId,
        Status = EvaluationStatus.InProgress,
        Action = "Started",
        ActionDate = DateTime.UtcNow
    });
    await _context.SaveChangesAsync();

    return MapToDto(created);
}

public async Task<EvaluationDto> SubmitEvaluationAsync(SubmitEvaluationDto dto)
{
    // ... mevcut submission kodu ...

    evaluation.Status = EvaluationStatus.Completed;
    evaluation.CompletedAt = DateTime.UtcNow;

    // YENİ: History kaydı
    await _context.EvaluationHistories.AddAsync(new EvaluationHistory
    {
        EvaluationId = evaluation.Id,
        UserId = evaluation.EvaluatorId,
        Status = EvaluationStatus.Completed,
        Action = "Submitted",
        ActionDate = DateTime.UtcNow,
        ScoreSnapshot = evaluation.TotalScore,
        AnsweredQuestionsCount = dto.Answers.Count,
        TotalQuestionsCount = allQuestions.Count
    });

