}

public interface IAuditLogRepository
{
    Task<List<AuditLog>> GetByEntityAsync(string entityName, Guid entityId);
    Task<List<AuditLog>> GetByUserAsync(string userId, DateTime? startDate = null, DateTime? endDate = null);
    Task<List<AuditLog>> GetByDateRangeAsync(DateTime startDate, DateTime endDate);
}

[HttpGet("{id}/history")]
public async Task<ActionResult<List<EvaluationHistoryDto>>> GetEvaluationHistory(Guid id)
{
    var history = await _context.EvaluationHistories
        .Include(h => h.User)
        .Where(h => h.EvaluationId == id)
        .OrderByDescending(h => h.ActionDate)
        .ToListAsync();

    var result = history.Select(h => new EvaluationHistoryDto
    {
        Id = h.Id,
        Action = h.Action,
        Status = h.Status.ToString(),
        UserName = h.User != null ? $"{h.User.FirstName} {h.User.LastName}" : "External User",
        ActionDate = h.ActionDate,
        ScoreSnapshot = h.ScoreSnapshot,
        AnsweredQuestionsCount = h.AnsweredQuestionsCount,
        TotalQuestionsCount = h.TotalQuestionsCount
    }).ToList();

    return Ok(result);
}

[HttpGet("audit-logs")]
[Authorize(Roles = "Admin")]
public async Task<ActionResult<List<AuditLogDto>>> GetAuditLogs(
    [FromQuery] string? entityName = null,
    [FromQuery] DateTime? startDate = null,
    [FromQuery] DateTime? endDate = null)
{
    var query = _context.AuditLogs.AsQueryable();

    if (!string.IsNullOrEmpty(entityName))
        query = query.Where(a => a.EntityName == entityName);

    if (startDate.HasValue)
        query = query.Where(a => a.Timestamp >= startDate.Value);

    if (endDate.HasValue)
        query = query.Where(a => a.Timestamp <= endDate.Value);

    var logs = await query
        .OrderByDescending(a => a.Timestamp)
        .Take(1000)  // Limit
        .ToListAsync();

    return Ok(logs);
}
